import sim, mujoco, numpy as np
s=sim.Sim()
# baseline controller hold with bias + pd
home=s._initial_qpos.copy()

def rollout(extra=None,steps=200,delta=50):
    s2=sim.Sim();
    if extra:
        idx,val=extra
    else:
        idx,val=None,0
    xs=[]
    for t in range(steps):
        mujoco.mj_inverse(s2.model,s2.data)
        for i in range(s2.model.nu):
            jid=int(s2.model.actuator_trnid[i,0]); qadr=int(s2.model.jnt_qposadr[jid]); dof=int(s2.model.jnt_dofadr[jid])
            u=-float(s2.data.qfrc_bias[dof]) + 120*(home[qadr]-s2.data.qpos[qadr]) - 8*float(s2.data.qvel[dof])
            if i==idx:
                u += val
            lo,hi=s2.model.actuator_ctrlrange[i];
            s2.data.ctrl[i]=np.clip(u,lo,hi)
        s2.step(1)
        xs.append(s2.pelvis_position()[0])
    return xs[0],xs[-1],min(xs),max(xs),s2.torso_up(),s2.pelvis_position()[2]

for i,name in enumerate(sim.Sim().actuator_names()):
    b = rollout((i,50),120,)
    print(i,name,b)
